import{_ as i,o,c as t,ae as r}from"./chunks/framework.RRduUuAx.js";const q=JSON.parse('{"title":"多账本功能说明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh/guide/04-multi-ledger-guide.md","filePath":"v1/zh/guide/04-multi-ledger-guide.md"}'),a={name:"v1/zh/guide/04-multi-ledger-guide.md"};function n(s,l,e,g,h,u){return o(),t("div",null,[...l[0]||(l[0]=[r('<h1 id="多账本功能说明" tabindex="-1">多账本功能说明 <a class="header-anchor" href="#多账本功能说明" aria-label="Permalink to &quot;多账本功能说明&quot;">​</a></h1><h2 id="📋-概述" tabindex="-1">📋 概述 <a class="header-anchor" href="#📋-概述" aria-label="Permalink to &quot;📋 概述&quot;">​</a></h2><p>考拉记账支持创建多个账本，方便您管理不同类型的财务记录。每个账本可以独立设置名称、货币、分类等，非常适合以下场景：</p><ul><li><strong>个人账本</strong>：记录个人日常收支</li><li><strong>家庭账本</strong>：记录家庭共同开支</li><li><strong>旅行账本</strong>：记录旅行期间的支出</li><li><strong>宝宝账本</strong>：记录宝宝的成长开支</li><li><strong>汽车账本</strong>：记录汽车相关的费用</li><li><strong>装修账本</strong>：记录装修项目的支出</li><li><strong>生意账本</strong>：记录生意往来的收支</li></ul><hr><h2 id="🚀-快速开始" tabindex="-1">🚀 快速开始 <a class="header-anchor" href="#🚀-快速开始" aria-label="Permalink to &quot;🚀 快速开始&quot;">​</a></h2><h3 id="创建新账本" tabindex="-1">创建新账本 <a class="header-anchor" href="#创建新账本" aria-label="Permalink to &quot;创建新账本&quot;">​</a></h3><ol><li>打开考拉记账 App</li><li>点击底部导航栏的 <strong>&quot;设置&quot;</strong> 图标</li><li>在设置页面中找到 <strong>&quot;账本管理&quot;</strong> 选项</li><li>点击进入账本管理页面</li><li>点击右上角的 <strong>&quot;+&quot;</strong> 按钮</li><li>填写账本信息： <ul><li><strong>账本名称</strong>：输入账本名称（如：个人账本、家庭账本等）</li><li><strong>账本描述</strong>：可选，输入账本描述</li><li><strong>账本图标</strong>：选择账本图标（可选）</li><li><strong>账本货币</strong>：选择账本使用的货币（如：CNY、USD 等）</li></ul></li><li>点击 <strong>&quot;保存&quot;</strong> 完成创建</li></ol><blockquote><p>💡 <strong>提示</strong>：</p><ul><li>账本名称可以随时修改</li><li>账本货币可以在账本详情页面修改</li><li>每个账本的数据是独立的，互不影响</li></ul></blockquote><h3 id="切换账本" tabindex="-1">切换账本 <a class="header-anchor" href="#切换账本" aria-label="Permalink to &quot;切换账本&quot;">​</a></h3><ol><li>打开考拉记账 App</li><li>点击底部导航栏的 <strong>&quot;设置&quot;</strong> 图标</li><li>在设置页面中找到 <strong>&quot;账本管理&quot;</strong> 选项</li><li>点击进入账本管理页面</li><li>在账本列表中找到要切换的账本</li><li>点击账本卡片，即可切换到该账本</li></ol><blockquote><p>📝 <strong>注意</strong>：</p><ul><li>切换账本后，所有页面（概览、统计、账单列表等）都会显示该账本的数据</li><li>切换账本不会影响其他账本的数据</li><li>当前账本会在账本卡片上显示标识</li></ul></blockquote><hr><h2 id="📚-账本管理" tabindex="-1">📚 账本管理 <a class="header-anchor" href="#📚-账本管理" aria-label="Permalink to &quot;📚 账本管理&quot;">​</a></h2><h3 id="查看账本列表" tabindex="-1">查看账本列表 <a class="header-anchor" href="#查看账本列表" aria-label="Permalink to &quot;查看账本列表&quot;">​</a></h3><p>在账本管理页面，您可以：</p><ul><li><strong>查看所有账本</strong>：以网格形式显示所有账本</li><li><strong>查看账本信息</strong>：每个账本卡片显示： <ul><li>账本图标</li><li>账本名称</li><li>当前账本标识（如果已选中）</li></ul></li><li><strong>快速切换</strong>：点击账本卡片即可切换</li></ul><h3 id="编辑账本" tabindex="-1">编辑账本 <a class="header-anchor" href="#编辑账本" aria-label="Permalink to &quot;编辑账本&quot;">​</a></h3><ol><li>在账本管理页面，找到要编辑的账本</li><li>点击账本卡片右上角的 <strong>&quot;更多&quot;</strong> 按钮（三个点图标）</li><li>进入账本详情页面</li><li>可以修改： <ul><li><strong>账本名称</strong>：点击名称可以编辑</li><li><strong>账本描述</strong>：点击描述可以编辑</li><li><strong>账本图标</strong>：点击图标可以选择新图标</li><li><strong>账本货币</strong>：点击货币可以切换货币</li></ul></li><li>修改完成后，点击 <strong>&quot;保存&quot;</strong> 保存更改</li></ol><blockquote><p>⚠️ <strong>注意</strong>：</p><ul><li>修改账本货币后，所有账单的金额显示会相应调整</li><li>建议在创建账本时就选择正确的货币，避免后续修改</li></ul></blockquote><h3 id="删除账本" tabindex="-1">删除账本 <a class="header-anchor" href="#删除账本" aria-label="Permalink to &quot;删除账本&quot;">​</a></h3><ol><li>在账本管理页面，找到要删除的账本</li><li>点击账本卡片右上角的 <strong>&quot;更多&quot;</strong> 按钮</li><li>进入账本详情页面</li><li>点击 <strong>&quot;删除账本&quot;</strong> 按钮</li><li>确认删除（系统会提示删除后无法恢复）</li></ol><blockquote><p>⚠️ <strong>警告</strong>：</p><ul><li>删除账本会同时删除该账本下的所有账单数据</li><li>删除后账本会从本机移除；如已开启云同步，后续同步时也会从云端删除</li><li>删除操作不可在 App 内恢复，请谨慎操作</li><li>建议删除前先备份数据</li></ul></blockquote><hr><h2 id="💰-账本货币设置" tabindex="-1">💰 账本货币设置 <a class="header-anchor" href="#💰-账本货币设置" aria-label="Permalink to &quot;💰 账本货币设置&quot;">​</a></h2><h3 id="设置账本货币" tabindex="-1">设置账本货币 <a class="header-anchor" href="#设置账本货币" aria-label="Permalink to &quot;设置账本货币&quot;">​</a></h3><p>每个账本可以设置独立的货币，支持以下操作：</p><ol><li><strong>创建时设置</strong>：创建账本时选择货币</li><li><strong>后续修改</strong>：在账本详情页面可以修改货币</li></ol><h3 id="货币切换说明" tabindex="-1">货币切换说明 <a class="header-anchor" href="#货币切换说明" aria-label="Permalink to &quot;货币切换说明&quot;">​</a></h3><p>当您切换账本货币时：</p><ul><li><strong>汇率自动更新</strong>：系统会自动获取最新的汇率数据</li><li><strong>金额显示调整</strong>：所有账单的金额会按照新货币显示</li><li><strong>汇率缓存清除</strong>：系统会清除旧的汇率缓存，确保数据准确</li></ul><blockquote><p>📝 <strong>注意</strong>：</p><ul><li>切换货币不会改变账单的原始金额</li><li>系统会根据汇率自动换算显示金额</li><li>如果汇率数据不可用，可能会显示错误</li></ul></blockquote><h3 id="多币种支持" tabindex="-1">多币种支持 <a class="header-anchor" href="#多币种支持" aria-label="Permalink to &quot;多币种支持&quot;">​</a></h3><p>考拉记账支持多种货币，包括：</p><ul><li><strong>常用货币</strong>：CNY（人民币）、USD（美元）、EUR（欧元）、GBP（英镑）、JPY（日元）等</li><li><strong>其他货币</strong>：支持全球主要货币</li></ul><blockquote><p>💡 <strong>提示</strong>：如果您的账本需要处理多币种交易，建议：</p><ul><li>选择一个主要货币作为账本货币</li><li>记录交易时选择正确的交易货币</li><li>系统会自动换算到账本货币显示</li></ul></blockquote><hr><h2 id="📊-账本数据隔离" tabindex="-1">📊 账本数据隔离 <a class="header-anchor" href="#📊-账本数据隔离" aria-label="Permalink to &quot;📊 账本数据隔离&quot;">​</a></h2><h3 id="数据独立性" tabindex="-1">数据独立性 <a class="header-anchor" href="#数据独立性" aria-label="Permalink to &quot;数据独立性&quot;">​</a></h3><p>每个账本的数据是完全独立的：</p><ul><li><strong>账单数据</strong>：每个账本有独立的账单列表</li><li><strong>分类数据</strong>：每个账本有独立的分类设置</li><li><strong>标签数据</strong>：每个账本有独立的标签设置</li><li><strong>统计数据</strong>：每个账本有独立的统计数据</li></ul><blockquote><p>📝 <strong>注意</strong>：</p><ul><li>账户数据是设备级别的，所有账本共用</li><li>这意味着您可以在不同账本中使用相同的账户</li></ul></blockquote><h3 id="切换账本的影响" tabindex="-1">切换账本的影响 <a class="header-anchor" href="#切换账本的影响" aria-label="Permalink to &quot;切换账本的影响&quot;">​</a></h3><p>切换账本后：</p><ul><li><strong>概览页面</strong>：显示当前账本的统计数据</li><li><strong>统计页面</strong>：显示当前账本的图表数据</li><li><strong>账单列表</strong>：显示当前账本的账单记录</li><li><strong>账户列表</strong>：显示所有账户（账本共用）</li></ul><hr><h2 id="🔄-账本同步" tabindex="-1">🔄 账本同步 <a class="header-anchor" href="#🔄-账本同步" aria-label="Permalink to &quot;🔄 账本同步&quot;">​</a></h2><h3 id="云同步支持" tabindex="-1">云同步支持 <a class="header-anchor" href="#云同步支持" aria-label="Permalink to &quot;云同步支持&quot;">​</a></h3><p>考拉记账支持账本的云同步：</p><ul><li><strong>多设备同步</strong>：在不同设备上登录同一账号，账本数据会自动同步</li><li><strong>增量同步</strong>：只同步变更的数据，提高效率</li><li><strong>冲突处理</strong>：如果多设备同时修改，系统会优先保留本地未推送的改动</li></ul><h3 id="同步时机" tabindex="-1">同步时机 <a class="header-anchor" href="#同步时机" aria-label="Permalink to &quot;同步时机&quot;">​</a></h3><p>账本数据会在以下时机自动同步：</p><ul><li><strong>App 启动时</strong>：自动同步账本列表和当前账本数据</li><li><strong>手动同步</strong>：在设置页面点击云同步按钮</li><li><strong>数据变更后</strong>：创建、修改、删除账本后会自动标记为待同步</li></ul><blockquote><p>💡 <strong>提示</strong>：</p><ul><li>建议定期手动同步，确保数据最新</li><li>如果网络不稳定，可以稍后重试同步</li></ul></blockquote><hr><h2 id="🎨-账本类型说明" tabindex="-1">🎨 账本类型说明 <a class="header-anchor" href="#🎨-账本类型说明" aria-label="Permalink to &quot;🎨 账本类型说明&quot;">​</a></h2><p>考拉记账内置了多种账本类型，每种类型有不同的分类预设：</p><h3 id="默认账本-全部收支" tabindex="-1">默认账本（全部收支） <a class="header-anchor" href="#默认账本-全部收支" aria-label="Permalink to &quot;默认账本（全部收支）&quot;">​</a></h3><ul><li><strong>支出分类</strong>：包含所有支出分类（除特定分类外）</li><li><strong>收入分类</strong>：包含所有收入分类（除特定分类外）</li><li><strong>适用场景</strong>：通用账本，适合大多数场景</li></ul><h3 id="旅游账本" tabindex="-1">旅游账本 <a class="header-anchor" href="#旅游账本" aria-label="Permalink to &quot;旅游账本&quot;">​</a></h3><ul><li><strong>支出分类</strong>：交通、住宿、餐饮、购物、娱乐、其他</li><li><strong>收入分类</strong>：退款、其他</li><li><strong>适用场景</strong>：记录旅行期间的支出</li></ul><h3 id="宝宝账本" tabindex="-1">宝宝账本 <a class="header-anchor" href="#宝宝账本" aria-label="Permalink to &quot;宝宝账本&quot;">​</a></h3><ul><li><strong>支出分类</strong>：奶粉、尿布、玩具、教育、医疗、其他</li><li><strong>收入分类</strong>：红包、其他</li><li><strong>适用场景</strong>：记录宝宝的成长开支</li></ul><h3 id="汽车账本" tabindex="-1">汽车账本 <a class="header-anchor" href="#汽车账本" aria-label="Permalink to &quot;汽车账本&quot;">​</a></h3><ul><li><strong>支出分类</strong>：油费、保养、保险、维修、停车、其他</li><li><strong>收入分类</strong>：其他</li><li><strong>适用场景</strong>：记录汽车相关的费用</li></ul><h3 id="宠物账本" tabindex="-1">宠物账本 <a class="header-anchor" href="#宠物账本" aria-label="Permalink to &quot;宠物账本&quot;">​</a></h3><ul><li><strong>支出分类</strong>：食物、医疗、用品、美容、其他</li><li><strong>收入分类</strong>：其他</li><li><strong>适用场景</strong>：记录宠物的日常开支</li></ul><h3 id="装修账本" tabindex="-1">装修账本 <a class="header-anchor" href="#装修账本" aria-label="Permalink to &quot;装修账本&quot;">​</a></h3><ul><li><strong>支出分类</strong>：材料、人工、设计、家具、其他</li><li><strong>收入分类</strong>：其他</li><li><strong>适用场景</strong>：记录装修项目的支出</li></ul><h3 id="结婚账本" tabindex="-1">结婚账本 <a class="header-anchor" href="#结婚账本" aria-label="Permalink to &quot;结婚账本&quot;">​</a></h3><ul><li><strong>支出分类</strong>：婚纱、酒店、摄影、礼品、其他</li><li><strong>收入分类</strong>：礼金、其他</li><li><strong>适用场景</strong>：记录结婚相关的收支</li></ul><h3 id="人情账本" tabindex="-1">人情账本 <a class="header-anchor" href="#人情账本" aria-label="Permalink to &quot;人情账本&quot;">​</a></h3><ul><li><strong>支出分类</strong>：礼金、聚餐、礼品、其他</li><li><strong>收入分类</strong>：礼金、其他</li><li><strong>适用场景</strong>：记录人情往来的收支</li></ul><h3 id="生意账本" tabindex="-1">生意账本 <a class="header-anchor" href="#生意账本" aria-label="Permalink to &quot;生意账本&quot;">​</a></h3><ul><li><strong>支出分类</strong>：进货、租金、工资、税费、其他</li><li><strong>收入分类</strong>：销售收入、其他</li><li><strong>适用场景</strong>：记录生意往来的收支</li></ul><blockquote><p>💡 <strong>提示</strong>：</p><ul><li>创建账本时可以选择账本类型</li><li>不同类型的账本有不同的分类预设</li><li>您也可以创建自定义账本，手动设置分类</li></ul></blockquote><hr><h2 id="🔧-常见问题" tabindex="-1">🔧 常见问题 <a class="header-anchor" href="#🔧-常见问题" aria-label="Permalink to &quot;🔧 常见问题&quot;">​</a></h2><h3 id="q1-可以创建多少个账本" tabindex="-1">Q1：可以创建多少个账本？ <a class="header-anchor" href="#q1-可以创建多少个账本" aria-label="Permalink to &quot;Q1：可以创建多少个账本？&quot;">​</a></h3><p><strong>A：</strong> 当前最多可创建 <strong>50</strong> 个账本，但建议：</p><ul><li>根据实际需求创建，不要创建过多</li><li>每个账本都会占用存储空间</li><li>账本过多可能会影响 App 性能</li></ul><h3 id="q2-可以删除账本吗" tabindex="-1">Q2：可以删除账本吗？ <a class="header-anchor" href="#q2-可以删除账本吗" aria-label="Permalink to &quot;Q2：可以删除账本吗？&quot;">​</a></h3><p><strong>A：</strong> 可以，但请注意：</p><ul><li>删除账本会同时删除该账本下的所有数据</li><li>删除后账本会从本机移除；如已开启云同步，后续同步时也会从云端删除</li><li>删除操作不可在 App 内恢复，请谨慎操作</li><li>建议删除前先备份数据</li></ul><h3 id="q3-账本数据会同步吗" tabindex="-1">Q3：账本数据会同步吗？ <a class="header-anchor" href="#q3-账本数据会同步吗" aria-label="Permalink to &quot;Q3：账本数据会同步吗？&quot;">​</a></h3><p><strong>A：</strong> 会的。如果已登录账号，账本数据会自动同步到云端，可以在多设备间同步。</p><h3 id="q4-可以修改账本类型吗" tabindex="-1">Q4：可以修改账本类型吗？ <a class="header-anchor" href="#q4-可以修改账本类型吗" aria-label="Permalink to &quot;Q4：可以修改账本类型吗？&quot;">​</a></h3><p><strong>A：</strong> 目前不支持直接修改账本类型。如果需要，可以：</p><ul><li>创建新账本并选择正确的类型</li><li>将数据迁移到新账本</li><li>删除旧账本</li></ul><h3 id="q5-账户是账本级别的吗" tabindex="-1">Q5：账户是账本级别的吗？ <a class="header-anchor" href="#q5-账户是账本级别的吗" aria-label="Permalink to &quot;Q5：账户是账本级别的吗？&quot;">​</a></h3><p><strong>A：</strong> 不是。账户是设备级别的，所有账本共用。这意味着：</p><ul><li>您可以在不同账本中使用相同的账户</li><li>账户余额是所有账本共享的</li><li>如果需要在不同账本中使用不同的账户，可以创建多个同名账户（不推荐）</li></ul><h3 id="q6-切换账本会影响其他账本吗" tabindex="-1">Q6：切换账本会影响其他账本吗？ <a class="header-anchor" href="#q6-切换账本会影响其他账本吗" aria-label="Permalink to &quot;Q6：切换账本会影响其他账本吗？&quot;">​</a></h3><p><strong>A：</strong> 不会。每个账本的数据是完全独立的，切换账本不会影响其他账本的数据。</p><hr><h2 id="💡-使用技巧" tabindex="-1">💡 使用技巧 <a class="header-anchor" href="#💡-使用技巧" aria-label="Permalink to &quot;💡 使用技巧&quot;">​</a></h2><ol><li><strong>合理分类</strong>：根据实际需求创建账本，不要创建过多</li><li><strong>定期整理</strong>：定期检查账本列表，删除不需要的账本</li><li><strong>数据备份</strong>：重要账本建议定期备份，以防数据丢失</li><li><strong>命名规范</strong>：使用清晰的账本名称，方便识别和管理</li><li><strong>货币选择</strong>：根据账本用途选择合适的货币，避免频繁切换</li></ol><hr><p><strong>最后更新</strong>：2026年1月</p>',99)])])}const c=i(a,[["render",n]]);export{q as __pageData,c as default};
